function replaceOnce(s,a,b,l){const i=s.indexOf(a);if(i<0)fail('anchor_missing:'+l);if(s.indexOf(a,i+1)>=0)fail('anchor_not_unique:'+l);return s.slice(0,i)+b+s.slice(i+a.length)}
function exec(f,args,opt={}){const r=cp.spawnSync(f,args,{encoding:'utf8',maxBuffer:8*1024*1024,...opt});if(r.error)fail('exec_error:'+f+':'+r.error.message);if(r.status!==0)fail('exec_failed:'+f+':'+r.status+':'+String(r.stderr||'').slice(-1800));return r}
