function helperPreflight(c){const tmp='/tmp/prhm-v11-dashboard-helper-'+process.pid+'.js';try{fs.writeFileSync(tmp,c.helper,{mode:0o700});const r=exec('/usr/local/bin/prhm-node',[tmp,'--preflight-only'],{timeout:120000});const x=JSON.parse(String(r.stdout||'').trim());if(x.ok!==true||x.preflight_only!==true||x.action!==ACTION||x.production_mutation!==false||x.database_mutation!==false||x.business_mutation!==false||x.p0_live!==false||x.p0_decision!==false||x.proposal_send!==false||x.bid_send!==false||x.auto_send!==false||x.candidate_snapshot?.schema_version!=='prhm.company-os-dashboard.snapshot.v2')fail('persian_helper_preflight_invalid');return x}finally{try{fs.unlinkSync(tmp)}catch{}}}
